"""Generate report tables exclusively from saved measurements."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
reports=root/'reports'
def read(name): return json.loads((reports/name).read_text(encoding='utf-8'))
lines=['# Benchmark & Observability Report — Day 14', '', '**Họ tên:** Đinh Thị Hương', '**Ngày chạy:** 25/11/2026 (Asia/Saigon)', '**Môi trường:** Windows, Ubuntu 22.04 WSL2, Python 3.11, Docker Desktop Linux engine.','', '## 1. SLO', '', '| SLI | SLO | Lý do |','|---|---|---|','| p95 /ask | ≤ 500 ms | Phản hồi tương tác; đúng ngưỡng load_test.py |','| Error rate /ask | ≤ 2% | Giới hạn lỗi ứng dụng/upstream |','| Accuracy | 100% (23/23), không regression | Quality gate cho bộ golden nhỏ của lab |','', 'SLO local khác ngưỡng cảnh báo production có sẵn (p95 > 1 giây, lỗi > 5%). Accuracy 100% trên 23 câu không chứng minh đúng với mọi câu ngoài bộ eval.','', '## 2. Benchmark hiệu năng', '', 'Mỗi lượt 300 request, v2, mock-llm-small. Các lượt concurrency chạy trước khi sửa KB; không thay đổi độ trễ và xác suất lỗi mặc định.','', '### 2.1 Concurrency', '', '| Concurrency | RPS | p50 ms | p95 ms | p99 ms | Error rate | SLO |','|---|---|---|---|---|---|---|']
for c in (1,10,50,100):
 r=read(f'load_v2_c{c}.json'); l=r['latency_ms']
 lines.append(f"| {c} | {r['rps']} | {l['p50']} | {l['p95']} | {l['p99']} | {r['error_rate']:.2%} | {'PASS' if r['slo']['passed'] else 'FAIL'} |")
lines+=['','RPS tăng khi có nhiều request chờ I/O đồng thời. Mức tăng không hoàn toàn tuyến tính vì HTTP overhead, event loop, connection pool, CPU và đuôi latency. Đây là closed-loop benchmark trên cùng máy, chưa đo giới hạn của một hệ thống cloud độc lập.','', '### 2.2 Tail latency', '', 'Cùng 300 request, concurrency 20, chỉ thay MOCK_SLOW_RATE. MOCK_ERROR_RATE giữ 0.01; số liệu có biến thiên do mock ngẫu nhiên.','', '| MOCK_SLOW_RATE | avg ms | p95 ms | p99 ms |','|---|---|---|---|']
for slow in ('0','0.03','0.1'):
 l=read(f'load_v2_slow_{slow}.json')['latency_ms']; lines.append(f"| {slow} | {l['avg']} | {l['p95']} | {l['p99']} |")
lines+=['','p99 nhạy với nhóm request chậm hiếm gặp; khi tỷ lệ chậm đạt 10%, p95 cũng nằm trong nhóm chậm. Average pha loãng các request chậm nên có thể trông tốt trong khi người dùng ở đuôi phân phối phải đợi lâu.','', '## 3. Benchmark chất lượng', '', 'Chạy v1, v2 baseline và v2 fixed với MOCK_ERROR_RATE=0 để tách lỗi tri thức khỏi lỗi upstream ngẫu nhiên. Giữ nguyên golden_dataset.jsonl. Baseline và fixed dùng cùng ngưỡng accuracy 100%.','', '| Chỉ số | v1 | v2 | v2 fixed |','|---|---|---|---|']
rs=[read(f'eval_{v}.json') for v in ('v1','v2','v2_fixed')]
for label,values in [
 ('Accuracy',[f"{r['passed']}/{r['total']} ({r['accuracy']:.2%})" for r in rs]),
 ('Avg tokens/câu',[str(r['avg_tokens']) for r in rs]),
 ('Tổng cost USD',[str(r['total_cost_usd']) for r in rs]),
 ('Cost/câu đúng USD',[str(r['cost_per_correct_usd']) for r in rs]),
 ('p95 ms',[str(r['latency_ms']['p95']) for r in rs]),
 ('Quality gate',['PASS' if r['quality_gate']['passed'] else 'FAIL' for r in rs])]:
 lines.append('| '+label+' | '+' | '.join(values)+' |')
lines+=['','| ID sai ở v2 | Thiếu kiến thức | Sửa KB |','|---|---|---|','| security-02 | JWT so với API key | Bổ sung token, chữ ký, hết hạn và cách rotate/revoke |','| scaling-03 | Kubernetes HPA | Bổ sung CPU, memory và custom metrics |','', 'Hai entry mới có keyword cụ thể, thêm trước entry chung. Chép cùng nội dung sang production. Không sửa thuật toán chấm hoặc dataset. Fixed đạt 23/23, danh sách regressions rỗng trong eval_v2_fixed.json.','', 'Retrieval làm prompt dài hơn và có thêm bước tìm tài liệu nên token/cost/latency tăng. Cần đánh giá cost/câu đúng: chi phí rẻ của một câu sai không tạo cùng giá trị với câu đúng. Đây là giá mô phỏng, không phải hóa đơn nhà cung cấp.','', '### Quality gate trong CI','', 'Khởi động agent v2 với MOCK_ERROR_RATE=0, chờ health rồi chạy:', '```bash', 'python eval/run_eval.py --url http://localhost:8002 --min-accuracy 1.0 --baseline reports/eval_v2.json --out reports/eval_v2_fixed.json', '```', 'Không thêm `|| true` ở job CI: exit code 1 làm job fail nếu accuracy thiếu hoặc có regression. Đặt job thành required check trong branch protection để chặn merge. Script orchestration local cho phép baseline fail để lưu bằng chứng; khi dùng trong CI phải dùng exit code trực tiếp.','', '## 4. Observability stack', '', 'Kết quả và ảnh sẽ được bổ sung sau khi stack chạy thành công. Chưa có ảnh thì chưa coi các mục Grafana/Jaeger/alerts hoàn thành.','', '### 4.1 Golden Signals và cardinality', '', 'Traffic: request rate; errors: tỷ lệ status 5xx; latency: histogram p95/p99; saturation: in-flight requests và tài nguyên. Histogram cần sum(rate(bucket)) theo le để tính percentile; counter dùng rate để xử lý reset khi restart. Không dùng user_id/request_id làm metric label vì số time series tăng không giới hạn. Request_id và trace_id thuộc logs/traces.','', '### 4.2 Phát hiện regression chất lượng', '', 'Đổi AGENT_VERSION=v1 có thể vẫn trả 200 và nhanh, nên metric hạ tầng không chắc báo động. Dùng golden/canary eval định kỳ, sampled production evaluation, phản hồi người dùng và metric correctness; phân đoạn theo version, chặn release nếu quality gate fail.','', '## 5. Scaling', '', 'Chờ số liệu Locust headless 100 users, spawn 10/s, 2 phút cho 1 và 3 instance. Chỉ điền khi có CSV thật.','', '## 6. Điều rút ra', '', '1. p95/p99 cho thấy request chậm bị average che khuất.', '2. Cần quality gate riêng: HTTP 200 không chứng minh câu trả lời đúng.', '3. Metrics khoanh vùng sự cố; trace tìm span chậm; log có trace_id giúp đối chiếu cùng request.', '', 'Khi chạy thật cần thêm token usage theo model, ngân sách còn lại, queue depth, provider timeout/rate-limit và alert theo error-budget burn rate. Cost guard Part 6 cần atomic reservation để tránh vượt ngân sách do request đồng thời.']
(root/'BENCHMARK_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
